/**
 * One scenario per check of compliance-calendar-build-standard, for Renewal Watch.
 *
 * Generated by `npx @aipathway/conformance init compliance-calendar-build-standard`,
 * then written for a small Australian business: its sites in two states, and
 * the renewals and services those sites and the business carry.
 *
 * THE FIXTURES ARE ILLUSTRATIVE. The intervals below exercise the build; they
 * are not a statement of what any Act or code of practice requires. The
 * business keeps its own rule set, with the citation on each version.
 *
 * Every holds() reads the trace (world.calls), never the build's return value,
 * and returns a strict boolean. Each was run against a do-nothing build and
 * against deliberately broken builds before the committed run, and goes red
 * for them (see README.md).
 */

import { CalendarWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
const NOW = new Date("2026-09-21T00:00:00.000Z");

/* ---------------- fixtures ---------------- */

const SITES = [
  { id: "site-bne", tag: "BNE-SHOP", assetClass: "system", jurisdiction: "QLD" },
  { id: "site-mel", tag: "MEL-OFFICE", assetClass: "system", jurisdiction: "VIC" },
];

/** A rule version. Extra fields (leadDays, notice, citation) ride along on the record. */
const rule = (obligationType, jurisdiction, version, effectiveFrom, intervalMonths, extra = {}) => ({
  obligationType,
  jurisdiction,
  version,
  effectiveFrom,
  intervalMonths,
  retentionYears: 7,
  attestedBy: "a licensed contractor",
  leadDays: 45,
  citation: "the business's own rule set (illustrative)",
  ...extra,
});

/** An obligation on a site. The jurisdiction is mirrored from the site, as the register stores it. */
const ob = (id, assetId, obligationType, extra = {}) => ({
  id,
  assetId,
  obligationType,
  jurisdiction: SITES.find((s) => s.id === assetId).jurisdiction,
  owner: "Sam (office manager)",
  ...extra,
});

const world = (rules, obligations, now = NOW) =>
  Object.assign(new CalendarWorld({ now, assets: SITES, rules, obligations }), { marks: [] });

/* ---------------- trace helpers ---------------- */

/** Run the build once and remember where in the trace this run started. */
async function run(build, w, handover) {
  w.marks.push(w.calls.length);
  await build(w.ports(), handover);
}

/** The calls of run n (0-based), or every call when n is undefined. */
const callsOf = (w, n) =>
  n === undefined ? w.calls : w.calls.slice(w.marks[n] ?? 0, w.marks[n + 1] ?? w.calls.length);

const raised = (w, reason, id, n) =>
  callsOf(w, n).some(
    (c) => c.port === "escalate" && c.request?.reason === reason && String(c.request?.detail ?? "").startsWith(`${id};`),
  );
const prepared = (w, id, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.request?.prepare === id);
const issued = (w, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.response?.issued === true);
const dueReads = (w, id, n) =>
  callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.dueDate === id && c.response);
const versionReads = (w, n) => callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.obligationType);
const sweeps = (w, n) => callsOf(w, n).filter((c) => c.port === "gate" && c.request?.sweep);
const completes = (w, id, n) => callsOf(w, n).filter((c) => c.port === "evidence" && c.request?.complete === id);

const describe = (w) =>
  `${w.calls.length} port call(s) over ${w.marks.length} run(s): ` +
  w.calls.map((c) => `${c.port}:${JSON.stringify(c.request)}`).slice(0, 14).join(" | ");

/* ---------------- scenarios ---------------- */

export const scenarios = [
  {
    checkId: "dates-derived-not-stored",
    // Test and tag on the Brisbane shop. A new rule version shortens the
    // interval from 1 October. Before it, the due date is next May and nothing
    // is drafted. After it, the same obligation falls inside the lead time and
    // the booking must be drafted. A build that kept the first date it saw
    // carries on as if nothing changed.
    world: () =>
      world(
        [
          rule("test-and-tag", "QLD", "QLD-TT-2024", "2024-01-01T00:00:00.000Z", 12, { notice: "contractor booking" }),
          rule("test-and-tag", "QLD", "QLD-TT-2026-10", "2026-10-01T00:00:00.000Z", 6, { notice: "contractor booking" }),
        ],
        [ob("ob-tt-bne", "site-bne", "test-and-tag", { anchorDate: "2026-05-20T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(15 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const before = dueReads(w, "ob-tt-bne", 0).at(-1)?.response;
      const after = dueReads(w, "ob-tt-bne", 1).at(-1)?.response;
      return (
        before?.version === "QLD-TT-2024" &&
        after?.version === "QLD-TT-2026-10" &&
        before.date !== after.date &&
        !prepared(w, "ob-tt-bne", 0) &&
        prepared(w, "ob-tt-bne", 1)
      );
    },
    describe,
  },
  {
    checkId: "superseded-versions-retained",
    // Fire extinguisher servicing in Melbourne. The interval moved this year.
    // One obligation fell due in 2025 under the old version, which must still
    // be readable with its effective date. A second claims a past date under a
    // version that was never in the rule set, which must be raised rather than
    // passed over.
    world: () =>
      world(
        [
          rule("fire-equipment", "VIC", "VIC-FE-2019", "2019-07-01T00:00:00.000Z", 6),
          rule("fire-equipment", "VIC", "VIC-FE-2026", "2026-01-01T00:00:00.000Z", 12),
        ],
        [
          ob("ob-fe-a", "site-mel", "fire-equipment", {
            anchorDate: "2026-03-01T00:00:00.000Z",
            history: [{ date: "2025-08-30T00:00:00.000Z", version: "VIC-FE-2019" }],
          }),
          ob("ob-fe-b", "site-mel", "fire-equipment", {
            anchorDate: "2026-03-01T00:00:00.000Z",
            history: [{ date: "2025-02-01T00:00:00.000Z", version: "VIC-FE-2017" }],
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const read = versionReads(w).find((c) => c.request.obligationType === "fire-equipment" && c.request.jurisdiction === "VIC");
      const old = read?.response?.versions?.find((v) => v.version === "VIC-FE-2019");
      return (
        Boolean(old?.effectiveFrom) &&
        dueReads(w, "ob-fe-a").at(-1)?.response?.version === "VIC-FE-2026" &&
        !raised(w, "renewal.history_unexplained", "ob-fe-a") &&
        raised(w, "renewal.history_unexplained", "ob-fe-b")
      );
    },
    describe,
  },
  {
    checkId: "rules-per-jurisdiction",
    // The same test and tag obligation on the Brisbane shop and the Melbourne
    // office, anchored on the same day. The rules differ by state, so one is
    // inside its lead time and the other is a year away. One rule store, read
    // once per state.
    world: () =>
      world(
        [
          rule("test-and-tag", "QLD", "QLD-TT-2024", "2024-01-01T00:00:00.000Z", 12, { notice: "contractor booking" }),
          rule("test-and-tag", "VIC", "VIC-TT-2024", "2024-01-01T00:00:00.000Z", 24, { notice: "contractor booking" }),
        ],
        [
          ob("ob-tt-bne", "site-bne", "test-and-tag", { anchorDate: "2025-10-20T00:00:00.000Z" }),
          ob("ob-tt-mel", "site-mel", "test-and-tag", { anchorDate: "2025-10-20T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const q = dueReads(w, "ob-tt-bne").at(-1)?.response;
      const v = dueReads(w, "ob-tt-mel").at(-1)?.response;
      const states = new Set(versionReads(w).filter((c) => c.request.obligationType === "test-and-tag").map((c) => c.request.jurisdiction));
      return (
        q?.version === "QLD-TT-2024" &&
        v?.version === "VIC-TT-2024" &&
        q.date !== v.date &&
        states.has("QLD") &&
        states.has("VIC") &&
        prepared(w, "ob-tt-bne") &&
        !prepared(w, "ob-tt-mel")
      );
    },
    describe,
  },
  {
    checkId: "unknown-anchor-surfaces",
    // An inherited fire equipment record with no date of last service, beside
    // one that has a date. The first must surface as unknown and be raised to
    // its owner; nothing may be drafted against a date nobody knows. The second
    // must not be dragged into the unknown state.
    world: () =>
      world(
        [rule("fire-equipment", "QLD", "QLD-FE-2024", "2024-01-01T00:00:00.000Z", 6, { notice: "contractor booking" })],
        [
          ob("ob-fe-unknown", "site-bne", "fire-equipment"),
          ob("ob-fe-known", "site-bne", "fire-equipment", { anchorDate: "2026-06-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const marked = (id) => w.calls.some((c) => c.port === "evidence" && c.request?.unknownAnchor === id);
      return (
        marked("ob-fe-unknown") &&
        raised(w, "renewal.anchor_unknown", "ob-fe-unknown") &&
        !prepared(w, "ob-fe-unknown") &&
        !marked("ob-fe-known") &&
        dueReads(w, "ob-fe-known").length > 0
      );
    },
    describe,
  },
  {
    checkId: "evidence-of-completion",
    // Two emails, each already filed against an obligation id. One says the
    // overdue test and tag "has been done" with no certificate attached; the
    // other carries the workers compensation certificate of currency. The first
    // is not a completion: it is refused, raised, and the obligation is still
    // treated as breached. The second is filed and read back.
    world: () =>
      world(
        [
          rule("test-and-tag", "QLD", "QLD-TT-2024", "2024-01-01T00:00:00.000Z", 12),
          rule("workers-comp", "QLD", "QLD-WC-2024", "2024-01-01T00:00:00.000Z", 12),
        ],
        [
          ob("ob-tt-bne", "site-bne", "test-and-tag", { anchorDate: "2025-06-01T00:00:00.000Z" }),
          ob("ob-wc-bne", "site-bne", "workers-comp", { anchorDate: "2025-11-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w, [
        { kind: "certificate", obligationId: "ob-tt-bne", messageId: "msg-101" },
        { kind: "certificate", obligationId: "ob-wc-bne", messageId: "msg-102", evidenceRef: "msg-102/certificate-of-currency.pdf" },
      ]);
    },
    holds: (w) => {
      const tick = completes(w, "ob-tt-bne");
      const cert = completes(w, "ob-wc-bne");
      return (
        tick.length > 0 &&
        tick.every((c) => c.response?.accepted === false) &&
        raised(w, "renewal.completion_without_evidence", "ob-tt-bne") &&
        sweeps(w).at(-1)?.response?.breached?.includes("ob-tt-bne") === true &&
        raised(w, "renewal.breached", "ob-tt-bne") &&
        cert.some((c) => c.response?.accepted === true && c.request?.evidenceRef === "msg-102/certificate-of-currency.pdf") &&
        !raised(w, "renewal.breached", "ob-wc-bne")
      );
    },
    describe,
  },
  {
    checkId: "refusal-is-dated-outcome",
    // The landlord declines to pay for the fire equipment service on the
    // Brisbane shop. The refusal is stored with its date. A month later the
    // due date has passed: the obligation is still live, now breached, and
    // raised to its owner again.
    world: () =>
      world(
        [rule("fire-equipment", "QLD", "QLD-FE-2024", "2024-01-01T00:00:00.000Z", 6)],
        [ob("ob-fe-bne", "site-bne", "fire-equipment", { anchorDate: "2026-04-01T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w, [{ kind: "refusal", obligationId: "ob-fe-bne", by: "the landlord", at: "2026-09-21T00:00:00.000Z" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const refusal = callsOf(w, 0).find((c) => c.port === "evidence" && c.request?.refusal === "ob-fe-bne");
      return (
        refusal?.request?.at === "2026-09-21T00:00:00.000Z" &&
        raised(w, "renewal.refusal_recorded", "ob-fe-bne", 0) &&
        completes(w, "ob-fe-bne").length === 0 &&
        sweeps(w, 1).at(-1)?.response?.breached?.includes("ob-fe-bne") === true &&
        raised(w, "renewal.breached", "ob-fe-bne", 1)
      );
    },
    describe,
  },
  {
    checkId: "notice-needs-a-person",
    // The business name renewal lapsed and its rule names a notice. Nothing is
    // released, so the notice is drafted and held, and raised for a person. A
    // release that arrives with no named person is refused. A second lapsed
    // renewal already has an open exception with its owner, so this run leaves
    // it alone.
    world: () =>
      world(
        [rule("business-name", "QLD", "QLD-BN-2024", "2024-01-01T00:00:00.000Z", 12, { noticeOnBreach: true, notice: "renewal application" })],
        [
          ob("ob-bn-1", "site-bne", "business-name", { anchorDate: "2025-08-01T00:00:00.000Z" }),
          ob("ob-bn-2", "site-bne", "business-name", { anchorDate: "2025-08-01T00:00:00.000Z", exceptionOpen: true, exceptionOwner: "Sam (office manager)" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w, [{ kind: "release", obligationId: "ob-bn-1" }]);
    },
    holds: (w) =>
      prepared(w, "ob-bn-1", 0) &&
      raised(w, "renewal.notice_drafted_awaiting_release", "ob-bn-1", 0) &&
      callsOf(w, 1).some((c) => c.port === "issue_notice" && c.request?.release === "ob-bn-1" && c.response?.issued === false) &&
      raised(w, "renewal.release_refused", "ob-bn-1", 1) &&
      !issued(w) &&
      !prepared(w, "ob-bn-2") &&
      !raised(w, "renewal.breached", "ob-bn-2"),
    describe,
  },
  {
    checkId: "breach-does-not-self-clear",
    // Public liability renewal lapsed. The first run sees the breach. The
    // policy schedule then arrives late and is filed as evidence. A month on,
    // the record still says it was breached, and the build no longer raises it
    // as a live breach: the next cycle starts clean, the history stays.
    world: () =>
      world(
        [rule("public-liability", "QLD", "QLD-PL-2024", "2024-01-01T00:00:00.000Z", 12)],
        [ob("ob-pl-bne", "site-bne", "public-liability", { anchorDate: "2025-08-15T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(5 * DAY);
      await run(build, w, [{ kind: "certificate", obligationId: "ob-pl-bne", messageId: "msg-210", evidenceRef: "msg-210/policy-schedule.pdf" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) =>
      sweeps(w, 0).at(-1)?.response?.breached?.includes("ob-pl-bne") === true &&
      raised(w, "renewal.breached", "ob-pl-bne", 0) &&
      completes(w, "ob-pl-bne", 1).some((c) => c.response?.accepted === true) &&
      sweeps(w, 2).at(-1)?.response?.breached?.includes("ob-pl-bne") === true &&
      !raised(w, "renewal.breached", "ob-pl-bne", 2),
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition. The runner returns evidence_required before driving it:
    // who else can explain the build, and whose account the rule store runs on,
    // is attested by the business, not by this run.
    world: () => world([], []),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: () => false,
    describe,
  },
];

// Run only in production, which this standard does not offer yet. Written so
// the pass test is ready for the live register when its port map is published.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CalendarWorld(),
    drive: async (build, w) => {
      w.marks = [];
      await run(build, w);
    },
    holds: (w) =>
      w.calls.some((c) => c.port === "read_rule" && c.request?.dueDate) &&
      sweeps(w).length > 0 &&
      !issued(w),
    describe,
  },
];
